// Arduino Sketch
v#include <GxEPD2_BW.h>
#include <U8g2_for_Adafruit_GFX.h>
#include <Fonts/FreeMonoBold18pt7b.h>

// --- Настройка пинов ---
static const uint8_t EPD_BUSY = 21;
static const uint8_t EPD_CS = 10;
static const uint8_t EPD_RST = 6;
static const uint8_t EPD_DC = 7;
static const uint8_t EPD_SCK = 20;
static const uint8_t EPD_MOSI = 5;
static const uint8_t EPD_MISO = -1;

// --- Кнопки ---
const int BUTTON_DAY = 0;
const int BUTTON_MONTH = 1;

// --- Дисплей ---
GxEPD2_BW<GxEPD2_213_BN, GxEPD2_213_BN::HEIGHT> display(GxEPD2_213_BN(EPD_CS, EPD_DC, EPD_RST, EPD_BUSY));

// --- Адаптер для шрифтов U8g2 ---
U8G2_FOR_ADAFRUIT_GFX u8g2Fonts;

// --- Месяцы на русском ---
const char* months[] = {
  "\xD0\xAF\xD0\xBD\xD0\xB2\xD0\xB0\xD1\x80\xD1\x8C",  // Январь
  "\xD0\xA4\xD0\xB5\xD0\xB2\xD1\x80\xD0\xB0\xD0\xBB\xD1\x8C",  // Февраль
  "\xD0\x9C\xD0\xB0\xD1\x80\xD1\x82",  // Март
  "\xD0\x90\xD0\xBF\xD1\x80\xD0\xB5\xD0\xBB\xD1\x8C",  // Апрель
  "\xD0\x9C\xD0\xB0\xD0\xB9",  // Май
  "\xD0\x98\xD1\x8E\xD0\xBD\xD1\x8C",  // Июнь
  "\xD0\x98\xD1\x8E\xD0\xBB\xD1\x8C",  // Июль
  "\xD0\x90\xD0\xB2\xD0\xB3\xD1\x83\xD1\x81\xD1\x82",  // Август
  "\xD0\xA1\xD0\xB5\xD0\xBD\xD1\x82\xD1\x8F\xD0\xB1\xD1\x80\xD1\x8C",  // Сентябрь
  "\xD0\x9E\xD0\xBA\xD1\x82\xD1\x8F\xD0\xB1\xD1\x80\xD1\x8C",  // Октябрь
  "\xD0\x9D\xD0\xBE\xD1\x8F\xD0\xB1\xD1\x80\xD1\x8C",  // Ноябрь
  "\xD0\x94\xD0\xB5\xD0\xBA\xD0\xB0\xD0\xB1\xD1\x80\xD1\x8C"  // Декабрь
};

int currentMonth = 1;
int currentDay = 15;

// Функция получения дней в месяце
int getDaysInMonth(int month) {
  if (month == 2) return 28;
  if (month == 4 || month == 6 || month == 9 || month == 11) return 30;
  return 31;
}

// Функция обновления дисплея
void updateDisplay() {
  // Заголовок на РУССКОМ языке
  char headerText[] = "\xD0\xA1\xD0\x90\xD0\xA5\xD0\x90\xD0\xA0";  // САХАР
  char dateText[30];
  sprintf(dateText, "%d %s", currentDay, months[currentMonth - 1]);

  display.setFullWindow();
  display.firstPage();
  do {
    display.fillScreen(GxEPD_WHITE);
    display.setRotation(1);

    // ==========================================
    // === ЗАГОЛОВОК "САХАР" (увеличенный шрифт) ===
    // ==========================================
    u8g2Fonts.setFont(u8g2_font_inr24_t_cyrillic);  // Крупный шрифт с кириллицей
    u8g2Fonts.setForegroundColor(GxEPD_BLACK);
    u8g2Fonts.setBackgroundColor(GxEPD_WHITE);

    // Центрирование заголовка
    int header_width = u8g2Fonts.getUTF8Width(headerText);
    int header_x = (200 - header_width) / 2;
    int header_y = 35;  // Верхняя часть экрана

    u8g2Fonts.setCursor(header_x, header_y);
    u8g2Fonts.print(headerText);

    // ==========================================
    // === ДАТА (ЕЩЕ БОЛЕЕ КРУПНЫЙ ШРИФТ) ===
    // ==========================================
    // Используем самый крупный доступный шрифт с кириллицей
    u8g2Fonts.setFont(u8g2_font_inr24_t_cyrillic);

    // Центрирование даты
    int text_width = u8g2Fonts.getUTF8Width(dateText);
    int x1 = (200 - text_width) / 2;
    int y1 = 110;  // Центр экрана (немного ниже середины)

    u8g2Fonts.setCursor(x1, y1);
    u8g2Fonts.print(dateText);

  } while (display.nextPage());

  display.hibernate();
}

// --- Обработка кнопок ---
void handleButtons() {
  static unsigned long lastDayPress = 0;
  static unsigned long lastMonthPress = 0;
  unsigned long currentTime = millis();

  if (digitalRead(BUTTON_DAY) == LOW && (currentTime - lastDayPress) > 300) {
    lastDayPress = currentTime;
    currentDay++;
    int daysInMonth = getDaysInMonth(currentMonth);
    if (currentDay > daysInMonth) {
      currentDay = 1;
      currentMonth++;
      if (currentMonth > 12) currentMonth = 1;
    }
    updateDisplay();
  }

  if (digitalRead(BUTTON_MONTH) == LOW && (currentTime - lastMonthPress) > 300) {
    lastMonthPress = currentTime;
    currentMonth++;
    if (currentMonth > 12) currentMonth = 1;
    int daysInMonth = getDaysInMonth(currentMonth);
    if (currentDay > daysInMonth) currentDay = daysInMonth;
    updateDisplay();
  }
}

void setup() {
  Serial.begin(115200);

  pinMode(BUTTON_DAY, INPUT_PULLUP);
  pinMode(BUTTON_MONTH, INPUT_PULLUP);

  SPI.end();
  SPI.begin(EPD_SCK, EPD_MISO, EPD_MOSI, EPD_CS);
  display.init(115200, true, 2, false);
  display.setRotation(1);

  // Инициализация адаптера U8g2
  u8g2Fonts.begin(display);

  // Очистка
  display.setFullWindow();
  display.firstPage();
  do {
    display.fillScreen(GxEPD_WHITE);
  } while (display.nextPage());

  updateDisplay();
  Serial.println("Ready!");
}

void loop() {
  handleButtons();
  delay(10);
}
